INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is ''continuous dyeing'' as opposed to ''batch (exhaust) dyeing''?', '["Fabric moves continuously through a sequence of application, fixation, and washing stages (e.g., pad-steam) rather than being processed as a fixed batch soaked in a static/circulating bath","Continuous dyeing means the machine runs 24 hours a day regardless of fabric present","Continuous dyeing uses no chemicals at all, only physical pressure","There is no real difference between continuous and batch dyeing methods"]'::jsonb, 'Fabric moves continuously through a sequence of application, fixation, and washing stages (e.g., pad-steam) rather than being processed as a fixed batch soaked in a static/circulating bath', 'Continuous dyeing processes fabric in a moving, open-width sequence (apply dye → fix, often via steam or hot air → wash) at high speed and volume, whereas batch/exhaust dyeing treats a fixed lot of fabric or yarn in a bath over an extended cycle time until the dye exhausts onto it.', 1, '{"continuous-vs-batch-dyeing"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'Why is continuous dyeing generally more suitable for very large production volumes of a single, consistent shade, compared to batch dyeing?', '["Continuous lines process fabric at high, steady throughput once set up, making them efficient for long, consistent runs, while batch dyeing is more flexible for smaller, varied lots","Continuous dyeing is always cheaper for even a single small sample, with no volume consideration","Batch dyeing can only ever process one meter of fabric at a time","Continuous dyeing cannot process more than a few meters of fabric total, ever"]'::jsonb, 'Continuous lines process fabric at high, steady throughput once set up, making them efficient for long, consistent runs, while batch dyeing is more flexible for smaller, varied lots', 'Continuous dyeing lines have significant setup/changeover effort but then run very efficiently at high speed for long, consistent fabric runs; batch dyeing machines are more flexible for smaller, varied orders since each batch can use a different recipe with less changeover complexity.', 2, '{"continuous-dyeing-suitability"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What does ''exhaust dyeing'' mean as a general dyeing method category?', '["A method where the fabric/yarn is immersed in a dye bath and the dye gradually transfers (''exhausts'') from the liquor onto the substrate over time","A method where dye is applied only by printing paste through a screen","A method that uses no water at all, only dry heat","A method where the fabric is never actually placed in contact with any dye liquor"]'::jsonb, 'A method where the fabric/yarn is immersed in a dye bath and the dye gradually transfers (''exhausts'') from the liquor onto the substrate over time', 'Exhaust dyeing immerses the substrate in a dye liquor bath, and over a controlled process (often involving specific temperature ramps), dye molecules gradually migrate (''exhaust'') from the liquor onto/into the fiber until equilibrium or the desired depth is reached.', 1, '{"exhaust-dyeing"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'Why is a controlled, gradual temperature ramp-up often used during exhaust dyeing rather than adding fabric directly into a very hot dye bath?', '["A gradual ramp allows dye to exhaust more evenly across the fabric, preventing rapid, uneven initial uptake that could cause unlevel/patchy dyeing","Temperature ramp rate has no effect whatsoever on dyeing evenness","A rapid temperature spike always improves evenness compared to gradual heating","Gradual heating is done purely to save time, with no quality-related purpose"]'::jsonb, 'A gradual ramp allows dye to exhaust more evenly across the fabric, preventing rapid, uneven initial uptake that could cause unlevel/patchy dyeing', 'If dye exhausts too rapidly (e.g., from sudden high heat), some fabric areas may absorb dye faster than others before the liquor can properly circulate and equalize, causing unlevel/patchy shade; a controlled, gradual ramp gives time for even dye distribution before near-complete exhaustion.', 2, '{"temperature-ramp","dyeing-levelness"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is a ''dyeing cycle'' (or dyeing program) typically composed of, in a modern batch dyeing machine?', '["A sequence of controlled steps: loading, heating/dyeing at controlled temperature and time, rinsing, and unloading — often with intermediate chemical additions at specific points","A single, uncontrolled step of simply soaking fabric in cold water with no other stages","Only the final drying stage, with no dyeing or rinsing involved","A random, unplanned sequence with no defined steps"]'::jsonb, 'A sequence of controlled steps: loading, heating/dyeing at controlled temperature and time, rinsing, and unloading — often with intermediate chemical additions at specific points', 'A dyeing cycle is a carefully planned program specifying each stage''s temperature, time, and chemical addition points (e.g., salt addition, alkali addition, specific temperature holds) — precise control over this sequence is essential for consistent, reproducible dyeing results.', 1, '{"dyeing-cycle"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'What is the purpose of ''soaping'' (or ''soaping-off'') as a step after reactive dyeing of cotton?', '["To remove unfixed/hydrolyzed dye from the fiber surface, improving wash and rub fastness of the final product","To add additional color depth after the main dyeing step","To apply the initial size coating to warp yarn","To permanently increase the fabric''s flammability"]'::jsonb, 'To remove unfixed/hydrolyzed dye from the fiber surface, improving wash and rub fastness of the final product', 'During reactive dyeing, some dye reacts with water instead of the fiber (hydrolyzed dye) or remains loosely attached to the surface; a hot soaping-off wash (often with a detergent/soap-like agent) removes this unfixed dye, significantly improving the final wash and rub fastness.', 2, '{"soaping-off"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'Why would skipping or shortening the soaping-off step after reactive dyeing likely cause poor wash fastness complaints later?', '["Unfixed/hydrolyzed dye left on the fiber surface would easily wash out or rub off during the customer''s normal use, causing color bleeding/fading","Soaping-off has no relationship to wash fastness outcomes at all","Skipping soaping-off always improves wash fastness compared to doing it properly","Soaping-off is only a cosmetic step affecting shade brightness, unrelated to fastness"]'::jsonb, 'Unfixed/hydrolyzed dye left on the fiber surface would easily wash out or rub off during the customer''s normal use, causing color bleeding/fading', 'If unfixed surface dye isn''t properly removed via soaping-off, it remains loosely held and will bleed out during the customer''s first few washes (or rub off through wear) — a common root cause of wash-fastness/crocking complaints if this step is inadequate.', 2, '{"soaping-off","wash-fastness"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'What is a ''dyeing auxiliary'' role played specifically by an ''anti-migration agent'' in pad-batch or pad-steam dyeing?', '["To prevent dye from migrating/moving excessively within the fabric during drying or batching, which could cause uneven shade or tone-on-tone unevenness","To permanently bond the fabric to the dyeing machine rollers","To increase dye migration as much as possible for a deliberately blotchy effect","To remove all moisture from the fabric before any dye is applied"]'::jsonb, 'To prevent dye from migrating/moving excessively within the fabric during drying or batching, which could cause uneven shade or tone-on-tone unevenness', 'During drying (especially in continuous processes) or extended batching, unfixed dye in the liquid film on fabric can migrate toward areas of faster moisture evaporation, causing uneven shade; anti-migration agents help hold dye in place until proper fixation occurs, preventing this unevenness.', 2, '{"anti-migration-agent"}'::text[]);
